<?php
/**
 * Plugin Name: WCBR26 Badges no Playground
 * Description: Estilo do Profile Frame Generator com a identidade do WordCamp Brasil 2026.
 */

// O logo sai igual ao da produção: imagem da mídia de brasil.wordcamp.org/2026 e link para lá.
add_filter(
	'render_block_core/site-logo',
	function () {
		return '<div class="wp-block-site-logo"><a href="https://brasil.wordcamp.org/2026/" class="custom-logo-link" rel="home"><img width="150" height="59" src="https://brasil.wordcamp.org/2026/files/2026/08/logo-1.avif" class="custom-logo" alt="WordCamp Brasil 2026" decoding="async" /></a></div>';
	}
);

// Quem abre o link entra como admin, mas só quer o gerador.
add_filter( 'show_admin_bar', '__return_false' );

add_action(
	'wp_enqueue_scripts',
	function () {
		// Estilos dos blocos da consulta de patrocinadores, que no rodapé virou HTML fixo.
		wp_enqueue_style( 'wp-block-post-template' );
		wp_enqueue_style( 'wp-block-post-featured-image' );
		wp_add_inline_style( 'profileframegen-controls-style', '.ppfg-wrapper{--pfg-primary:var(--wp--preset--color--custom-orange-600,#c6360b);--pfg-primary-hover:var(--wp--preset--color--custom-orange-600,#c6360b);--pfg-primary-glow:transparent;--pfg-card-bg:var(--wp--preset--color--custom-white,#fff);--pfg-surface:var(--wp--preset--color--custom-sand-100,#fff8f1);--pfg-text:var(--wp--preset--color--custom-cyan-900,#003e3e);--pfg-text-muted:var(--wp--preset--color--custom-gray-700,#4a5654);--pfg-border:var(--wp--preset--color--custom-sand-300,#e8dccb);--pfg-radius:0;--pfg-radius-sm:0;--pfg-shadow:var(--wp--preset--shadow--shadow-2);border:2px solid var(--wp--preset--color--custom-cyan-900,#003e3e);font-family:var(--wp--preset--font-family--montserrat)}.ppfg-wrapper .ppfg-preview-section{background-color:var(--wp--preset--color--custom-sand-200,#f6eee4);background-image:none}.ppfg-wrapper .rendered-image{border-radius:0;box-shadow:var(--wp--preset--shadow--shadow-1)}.ppfg-wrapper .rendered-image #resultCanvas,.profile-frame-container #resultCanvas{border:0}.ppfg-wrapper .ppfg-title{font-family:var(--wp--preset--font-family--poppins);text-transform:uppercase;color:var(--wp--preset--color--custom-cyan-900,#003e3e)}.ppfg-wrapper .ppfg-label{font-family:var(--wp--preset--font-family--poppins);color:var(--wp--preset--color--custom-cyan-700,#00595d)}.ppfg-wrapper .ppfg-file-label{border-color:var(--wp--preset--color--custom-cyan-700,#00595d);background:var(--wp--preset--color--custom-sand-100,#fff8f1);color:var(--wp--preset--color--custom-cyan-900,#003e3e)}.ppfg-wrapper .ppfg-file-label .ppfg-upload-icon{border-radius:0;background:var(--wp--preset--color--custom-white,#fff);border-color:var(--wp--preset--color--custom-cyan-700,#00595d)}.ppfg-wrapper .ppfg-file-label .ppfg-upload-icon svg{color:var(--wp--preset--color--custom-cyan-700,#00595d)}.ppfg-wrapper .ppfg-file-label .ppfg-upload-hint{color:var(--wp--preset--color--custom-gray-700,#4a5654)}.ppfg-wrapper .ppfg-file-label:hover{border-color:var(--wp--preset--color--custom-orange-600,#c6360b);background:var(--wp--preset--color--custom-white,#fff);color:var(--wp--preset--color--custom-orange-600,#c6360b)}.ppfg-wrapper .ppfg-file-label:hover .ppfg-upload-icon{background:var(--wp--preset--color--custom-sand-100,#fff8f1);border-color:var(--wp--preset--color--custom-orange-600,#c6360b)}.ppfg-wrapper .ppfg-toolbar{border-radius:0;border:2px solid var(--wp--preset--color--custom-cyan-900,#003e3e);box-shadow:var(--wp--preset--shadow--shadow-2)}.ppfg-wrapper .ppfg-tool-btn{border-radius:0 !important;color:var(--wp--preset--color--custom-cyan-900,#003e3e) !important}.ppfg-wrapper .ppfg-tool-btn:hover{color:var(--wp--preset--color--custom-orange-600,#c6360b) !important}.ppfg-wrapper .ppfg-zoom-slider{accent-color:var(--wp--preset--color--custom-orange-600,#c6360b)}.ppfg-wrapper .ppfg-zoom-slider::-webkit-slider-runnable-track{background:var(--wp--preset--color--custom-sand-300,#e8dccb)}.ppfg-wrapper .ppfg-zoom-slider::-moz-range-track{background:var(--wp--preset--color--custom-sand-300,#e8dccb)}.ppfg-wrapper .ppfg-zoom-slider::-webkit-slider-thumb{border-radius:0;box-shadow:0.125rem 0.125rem 0 0 var(--wp--preset--color--custom-cyan-900,#003e3e)}.ppfg-wrapper .ppfg-zoom-slider::-moz-range-thumb{border-radius:0;box-shadow:0.125rem 0.125rem 0 0 var(--wp--preset--color--custom-cyan-900,#003e3e)}.ppfg-wrapper input:checked + .ppfg-toggle-slider{background-color:var(--wp--preset--color--custom-cyan-700,#00595d)}.ppfg-wrapper .ppfg-input{border-radius:0;border:2px solid var(--wp--preset--color--custom-cyan-700,#00595d)}.ppfg-wrapper .ppfg-input:focus{border-color:var(--wp--preset--color--custom-orange-600,#c6360b);box-shadow:none}.ppfg-wrapper .ppfg-btn-primary,.ppfg-wrapper .ppfg-btn-primary:active,.profile-frame-container #download-photo{background:var(--wp--preset--color--custom-orange-600,#c6360b) !important;border:2px solid var(--wp--preset--color--custom-orange-600,#c6360b) !important;border-radius:0;color:var(--wp--preset--color--custom-white,#fff) !important;font-family:var(--wp--preset--font-family--poppins);font-weight:600;text-transform:uppercase;box-shadow:var(--wp--preset--shadow--shadow-1) !important;transform:none}.ppfg-wrapper .ppfg-btn-primary:hover,.ppfg-wrapper .ppfg-btn-primary:focus-visible,.profile-frame-container #download-photo:hover{background:var(--wp--preset--color--custom-orange-600,#c6360b) !important;border:2px solid var(--wp--preset--color--custom-orange-600,#c6360b) !important;box-shadow:var(--wp--preset--shadow--shadow-2) !important;transform:none}.ppfg-wrapper .ppfg-btn-secondary{background:var(--wp--preset--color--custom-white,#fff) !important;border:2px solid var(--wp--preset--color--custom-cyan-700,#00595d) !important;border-radius:0;color:var(--wp--preset--color--custom-cyan-700,#00595d) !important;font-family:var(--wp--preset--font-family--poppins);text-transform:uppercase}.ppfg-wrapper .ppfg-btn-secondary:hover,.ppfg-wrapper .ppfg-btn-secondary:active{background:var(--wp--preset--color--custom-cyan-700,#00595d) !important;border-color:var(--wp--preset--color--custom-cyan-700,#00595d) !important;color:var(--wp--preset--color--custom-white,#fff) !important}.ppfg-wrapper .ppfg-btn-success{background-color:var(--wp--preset--color--custom-cyan-700,#00595d) !important;border-color:var(--wp--preset--color--custom-cyan-700,#00595d) !important}@media (max-width:1023px){.ppfg-wrapper:not(.ppfg-layout-bottom){flex-direction:column}.ppfg-wrapper .ppfg-controls-section{border-left:none;border-top:1px solid var(--pfg-border);width:100%;display:grid;grid-template-columns:repeat(auto-fit,minmax(16rem,1fr));align-items:start;gap:1rem;padding:1.25rem}.ppfg-wrapper .rendered-image{max-width:min(100%,30rem) !important}.ppfg-wrapper .ppfg-controls-section>:not(.ppfg-group){grid-column:1 / -1}.ppfg-wrapper .ppfg-controls-section>div:first-child:not(.ppfg-group){display:none}}@media (max-width:600px){.ppfg-wrapper{box-shadow:none}.ppfg-wrapper .ppfg-preview-section{padding:0.75rem !important;min-height:0}.ppfg-wrapper .ppfg-controls-section{padding:1rem;gap:0.75rem}.ppfg-wrapper .ppfg-group{padding:0.75rem}.ppfg-wrapper .ppfg-file-label{flex-direction:row;justify-content:center;gap:0.75rem;padding:0.75rem;text-align:left}.ppfg-wrapper .ppfg-file-label .ppfg-upload-icon{margin:0;flex:none}.ppfg-wrapper .ppfg-file-label .ppfg-upload-hint{display:none}.ppfg-instructions{padding:1rem 1rem 1rem 1.25rem}}.ppfg-instructions{--pfg-primary:var(--wp--preset--color--custom-orange-600,#c6360b);--pfg-text:var(--wp--preset--color--custom-cyan-900,#003e3e);--pfg-text-muted:var(--wp--preset--color--custom-gray-700,#4a5654);--pfg-radius:0;--pfg-shadow:none;background:var(--wp--preset--color--custom-sand-100,#fff8f1)}:where(.wp-block-navigation-overlay-close){color:inherit;font-family:inherit;font-size:inherit;font-style:inherit;font-weight:inherit;letter-spacing:inherit;line-height:inherit;text-transform:inherit}' );
	},
	20
);

// No primeiro carregamento o Playground às vezes responde 403 para os arquivos de wp-includes (jQuery),
// e o navegador guarda esse 403 no cache. Nesse caso a página busca de novo esses arquivos, ignorando o
// cache, e recarrega (até 5 vezes).
add_action(
	'wp_footer',
	function () {
		echo '<script>if(typeof jQuery==="undefined"){var n=+(sessionStorage.wcbrRecarregou||0);if(n<5){sessionStorage.wcbrRecarregou=n+1;var u=[].map.call(document.querySelectorAll("script[src],link[rel=stylesheet]"),function(e){return e.src||e.href});Promise.all(u.map(function(x){return fetch(x,{cache:"reload",mode:"no-cors"}).catch(function(){})})).then(function(){setTimeout(function(){location.reload()},1000*n)})}}</script>';
	},
	99
);
